import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"仙吕·一半儿秋日宫词","description":"","frontmatter":{"title":"仙吕·一半儿秋日宫词","date":"2026-11-11T00:00:00.000Z","seq":38,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/仙吕·一半儿秋日宫词.md","filePath":"blogs/元曲·张可久/仙吕·一半儿秋日宫词.md"}'),o={name:"blogs/元曲·张可久/仙吕·一半儿秋日宫词.md"};function c(l,a,n,_,r,m){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="仙吕·一半儿秋日宫词" tabindex="-1">仙吕·一半儿秋日宫词 <a class="header-anchor" href="#仙吕·一半儿秋日宫词" aria-label="Permalink to &quot;仙吕·一半儿秋日宫词&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">花边娇月静妆楼，叶底沧波冷翠沟，池上好风闲御舟。</p><p class="poem-stanza">可怜秋，一半儿芙蓉一半儿柳。</p><p class="poem-stanza">梅边枝横翠竹暮寒生，花淡纱窗残月明，人倚画楼羌笛声。</p><p class="poem-stanza">恼诗情，一半儿清香一半儿影。</p><p class="poem-stanza">情数层秋树隔雕檐，万朵晴云拥玉蟾，几缕夜香穿绣帘。</p><p class="poem-stanza">等潜潜，一半儿门开一半儿掩。</p><p class="poem-stanza">野桥酬耿子春海棠香雨污吟袍，薜荔空墙闲酒瓢，杨柳晓风凉野桥。</p><p class="poem-stanza">放诗豪，一半儿行书一半儿草。</p><p class="poem-stanza">赏牡丹锦裙吹上翠云枝，绿酒争传白玉卮，皓齿慢歌金缕词。</p><p class="poem-stanza">牡丹时，一半儿姚黄一半儿紫。</p><p class="poem-stanza">苍崖禅师退隐柳梢香露点荷衣，树杪斜阳明翠微，竹外浅沙涵钓矶。</p><p class="poem-stanza">乐忘归，一半儿青山一半儿水。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
